"use client";

import { useState } from "react";

const initialBatches = [
  {
    id: "MED-2026-001",
    medicine: "Paracetamol 500mg",
    quantity: "5,000",
    expiry: "08 Oct 2028",
    status: "ACTIVE",
    destination: "XYZ Distributor",
  },
  {
    id: "MED-2026-002",
    medicine: "Amoxicillin 250mg",
    quantity: "3,000",
    expiry: "05 Oct 2028",
    status: "ACTIVE",
    destination: "XYZ Pharmacy",
  },
  {
    id: "MED-2026-003",
    medicine: "Ibuprofen 400mg",
    quantity: "2,500",
    expiry: "15 Sep 2026",
    status: "EXPIRED",
    destination: "ABC Distributor",
  },
];

export default function Home() {
  const [showCreate, setShowCreate] = useState(false);
  const [batchList, setBatchList] = useState(initialBatches);

  const [form, setForm] = useState({
    medicine: "",
    batchId: "",
    quantity: "",
    manufacturingDate: "",
    expiryDate: "",
  });

  const handleChange = (e) => {
    const { name, value } = e.target;

    setForm((currentForm) => ({
      ...currentForm,
      [name]: value,
    }));
  };

  const handleCreateBatch = () => {
    const medicine = form.medicine.trim();
    const batchId = form.batchId.trim();
    const quantity = form.quantity.trim();

    if (!medicine) {
      alert("Please enter the medicine name.");
      return;
    }

    if (!batchId) {
      alert("Please enter the batch ID.");
      return;
    }

    if (!quantity) {
      alert("Please enter the quantity.");
      return;
    }

    if (!form.manufacturingDate) {
      alert("Please select the manufacturing date.");
      return;
    }

    if (!form.expiryDate) {
      alert("Please select the expiry date.");
      return;
    }

    const newBatch = {
      id: batchId,
      medicine: medicine,
      quantity: Number(quantity).toLocaleString(),
      expiry: new Date(form.expiryDate).toLocaleDateString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      }),
      status: "ACTIVE",
      destination: "Not Assigned",
    };

    setBatchList((currentBatches) => [
      newBatch,
      ...currentBatches,
    ]);

    setForm({
      medicine: "",
      batchId: "",
      quantity: "",
      manufacturingDate: "",
      expiryDate: "",
    });

    setShowCreate(false);

    alert("Batch created successfully!");
  };

  return (
    <div className="min-h-screen bg-slate-100 text-slate-900">
      
      {/* Sidebar */}
      <aside className="fixed left-0 top-0 h-screen w-64 bg-slate-900 text-white">
        <div className="p-6">
          <h1 className="text-2xl font-bold">MedTrace</h1>
          <p className="mt-1 text-sm text-slate-400">
            Medicine Supply Chain
          </p>
        </div>

        <nav className="px-4">
          <div className="mb-2 rounded-lg bg-blue-600 px-4 py-3">
            Dashboard
          </div>

          <div className="mb-2 rounded-lg px-4 py-3 text-slate-300 hover:bg-slate-800">
            Batches
          </div>

          <div className="mb-2 rounded-lg px-4 py-3 text-slate-300 hover:bg-slate-800">
            Transfers
          </div>

          <div className="mb-2 rounded-lg px-4 py-3 text-slate-300 hover:bg-slate-800">
            Verification
          </div>
        </nav>

        <div className="absolute bottom-6 left-6 right-6 rounded-lg bg-slate-800 p-4">
          <p className="text-sm text-slate-400">Logged in as</p>
          <p className="font-semibold">Manufacturer</p>
        </div>
      </aside>

      {/* Main Content */}
      <main className="ml-64 min-h-screen">
        
        {/* Header */}
        <header className="flex items-center justify-between border-b bg-white px-8 py-5">
          <div>
            <h2 className="text-2xl font-bold">
              Manufacturer Dashboard
            </h2>
            <p className="text-sm text-slate-500">
              Manage medicine batches and supply chain activity
            </p>
          </div>

          <button
            onClick={() => setShowCreate(true)}
            className="rounded-lg bg-blue-600 px-5 py-3 font-semibold text-white hover:bg-blue-700"
          >
            + Create Batch
          </button>
        </header>

        <div className="p-8">

          {/* Statistics */}
          <div className="grid grid-cols-1 gap-6 md:grid-cols-3">
            
            <div className="rounded-xl bg-white p-6 shadow-sm">
              <p className="text-sm text-slate-500">
                Total Batches
              </p>
              <p className="mt-2 text-3xl font-bold">
                {batchList.length}
              </p>
            </div>

            <div className="rounded-xl bg-white p-6 shadow-sm">
              <p className="text-sm text-slate-500">
                Active Batches
              </p>
              <p className="mt-2 text-3xl font-bold text-green-600">
                {
                  batchList.filter(
                    (batch) => batch.status === "ACTIVE"
                  ).length
                }
              </p>
            </div>

            <div className="rounded-xl bg-white p-6 shadow-sm">
              <p className="text-sm text-slate-500">
                Expired Batches
              </p>
              <p className="mt-2 text-3xl font-bold text-red-600">
                {
                  batchList.filter(
                    (batch) => batch.status === "EXPIRED"
                  ).length
                }
              </p>
            </div>

          </div>

          {/* Recent Batches */}
          <div className="mt-8 rounded-xl bg-white shadow-sm">
            <div className="flex items-center justify-between border-b p-6">
              <div>
                <h3 className="text-xl font-bold">
                  Recent Batches
                </h3>
                <p className="text-sm text-slate-500">
                  Recently created medicine batches
                </p>
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b bg-slate-50 text-left text-sm text-slate-500">
                    <th className="px-6 py-4">Batch ID</th>
                    <th className="px-6 py-4">Medicine</th>
                    <th className="px-6 py-4">Quantity</th>
                    <th className="px-6 py-4">Expiry</th>
                    <th className="px-6 py-4">Status</th>
                    <th className="px-6 py-4">Destination</th>
                  </tr>
                </thead>

                <tbody>
                  {batchList.map((batch) => (
                    <tr
                      key={batch.id}
                      className="border-b last:border-b-0"
                    >
                      <td className="px-6 py-4 font-semibold">
                        {batch.id}
                      </td>

                      <td className="px-6 py-4">
                        {batch.medicine}
                      </td>

                      <td className="px-6 py-4">
                        {batch.quantity}
                      </td>

                      <td className="px-6 py-4">
                        {batch.expiry}
                      </td>

                      <td className="px-6 py-4">
                        <span
                          className={`rounded-full px-3 py-1 text-xs font-semibold ${
                            batch.status === "ACTIVE"
                              ? "bg-green-100 text-green-700"
                              : "bg-red-100 text-red-700"
                          }`}
                        >
                          {batch.status}
                        </span>
                      </td>

                      <td className="px-6 py-4 text-slate-600">
                        {batch.destination}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

        </div>
      </main>

      {/* Create Batch Modal */}
      {showCreate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          
          <div className="w-full max-w-lg rounded-2xl bg-white shadow-2xl">
            
            {/* Modal Header */}
            <div className="flex items-center justify-between border-b p-6">
              <div>
                <h2 className="text-xl font-bold">
                  Create New Batch
                </h2>
                <p className="text-sm text-slate-500">
                  Enter medicine batch information
                </p>
              </div>

              <button
                onClick={() => setShowCreate(false)}
                className="text-2xl text-slate-400 hover:text-slate-700"
              >
                ×
              </button>
            </div>

            {/* Form */}
            <div className="space-y-5 p-6">

              <div>
                <label className="mb-2 block text-sm font-semibold">
                  Medicine Name
                </label>

                <input
                  type="text"
                  name="medicine"
                  value={form.medicine}
                  onChange={handleChange}
                  placeholder="e.g. Paracetamol 500mg"
                  className="w-full rounded-lg border px-4 py-3 outline-none focus:border-blue-500"
                />
              </div>

              <div>
                <label className="mb-2 block text-sm font-semibold">
                  Batch ID
                </label>

                <input
                  type="text"
                  name="batchId"
                  value={form.batchId}
                  onChange={handleChange}
                  placeholder="e.g. MED-2026-004"
                  className="w-full rounded-lg border px-4 py-3 outline-none focus:border-blue-500"
                />
              </div>

              <div>
                <label className="mb-2 block text-sm font-semibold">
                  Quantity
                </label>

                <input
                  type="number"
                  name="quantity"
                  value={form.quantity}
                  onChange={handleChange}
                  placeholder="e.g. 5000"
                  className="w-full rounded-lg border px-4 py-3 outline-none focus:border-blue-500"
                />
              </div>

              <div className="grid grid-cols-1 gap-4 md:grid-cols-2">

                <div>
                  <label className="mb-2 block text-sm font-semibold">
                    Manufacturing Date
                  </label>

                  <input
                    type="date"
                    name="manufacturingDate"
                    value={form.manufacturingDate}
                    onChange={handleChange}
                    className="w-full rounded-lg border px-4 py-3 outline-none focus:border-blue-500"
                  />
                </div>

                <div>
                  <label className="mb-2 block text-sm font-semibold">
                    Expiry Date
                  </label>

                  <input
                    type="date"
                    name="expiryDate"
                    value={form.expiryDate}
                    onChange={handleChange}
                    className="w-full rounded-lg border px-4 py-3 outline-none focus:border-blue-500"
                  />
                </div>

              </div>

              {/* Buttons */}
              <div className="flex justify-end gap-3 pt-2">

                <button
                  onClick={() => setShowCreate(false)}
                  className="rounded-lg border px-5 py-3 font-semibold text-slate-600 hover:bg-slate-50"
                >
                  Cancel
                </button>

                <button
                  onClick={handleCreateBatch}
                  className="rounded-lg bg-blue-600 px-5 py-3 font-semibold text-white hover:bg-blue-700"
                >
                  Create Batch
                </button>

              </div>

            </div>
          </div>
        </div>
      )}
    </div>
  );
}